import pytz
from dateutil.parser import parse

# Constants
TIME_FORMAT = "%d/%m/%y %H:%M:%S.%f"


from datetime import timedelta
from pytz.exceptions import AmbiguousTimeError, NonExistentTimeError


def _localize_with_dst_resolution(dt, tz):
    """Localize a naive datetime while handling DST edge cases deterministically."""
    try:
        return tz.localize(dt, is_dst=None)
    except AmbiguousTimeError:
        # Prefer standard time when the local clock repeats.
        return tz.localize(dt, is_dst=False)
    except NonExistentTimeError:
        # Prefer the DST side of the gap when the local clock skips forward.
        try:
            return tz.localize(dt, is_dst=True)
        except NonExistentTimeError:
            try:
                return tz.localize(dt, is_dst=False)
            except NonExistentTimeError:
                # Last resort: shift forward by one hour and localize.
                return tz.localize(dt + timedelta(hours=1), is_dst=None)


def task_func(time_string, from_tz, to_tz):
    source_tz = pytz.timezone(from_tz)
    target_tz = pytz.timezone(to_tz)

    dt = parse(time_string, dayfirst=True)

    if dt.tzinfo is None:
        dt = _localize_with_dst_resolution(dt, source_tz)
    else:
        # If the input already includes timezone information, convert it to the source
        # timezone first so the final conversion still reflects a proper timezone-aware flow.
        dt = dt.astimezone(source_tz)

    converted = dt.astimezone(target_tz)

    # Output in milliseconds, rounding to the nearest millisecond.
    converted = converted + timedelta(microseconds=500)
    return converted.strftime(TIME_FORMAT)[:-3]
